[
    {
        "title": "拼出大正方形",
        "description": "把四个全等直角三角形拼进一个边长为 $a+b$ 的正方形里。",
        "bubbleText": "先别急着算，咱们先看它们能拼成一个大正方形。",
        "bubblePos": {
            "x": 170,
            "y": 92
        }
    },
    {
        "title": "看出空缺",
        "description": "四个角被三角形占满后，中间留下一个边长为 $c$ 的小正方形。",
        "bubbleText": "中间这个小方块，就是我们等会儿要单独算的部分。",
        "bubblePos": {
            "x": 350,
            "y": 98
        }
    },
    {
        "title": "算总面积",
        "description": "大正方形面积是 $(a+b)^2$，也等于四个三角形面积和小正方形面积之和。",
        "bubbleText": "同一个图形，面积可以从两边一起算。",
        "bubblePos": {
            "x": 540,
            "y": 98
        }
    },
    {
        "title": "列出等式",
        "description": "所以 $(a+b)^2 = 4\\cdot\\frac{ab}{2} + c^2$，即 $a^2+2ab+b^2=2ab+c^2$。",
        "bubbleText": "四个三角形加中间小正方形，正好凑成整个大正方形。",
        "bubblePos": {
            "x": 240,
            "y": 288
        }
    },
    {
        "title": "移项整理",
        "description": "两边同时减去 $2ab$，得到 $a^2+b^2=c^2$。",
        "bubbleText": "把两边都有的 $2ab$ 去掉，剩下的就是勾股定理。",
        "bubblePos": {
            "x": 380,
            "y": 436
        }
    },
    {
        "title": "验证结论",
        "description": "检查式子两边来自同一个总面积，推导前后等量，所以结论成立。",
        "bubbleText": "这不是硬记公式，是把同一块面积用两种方法算出来。",
        "bubblePos": {
            "x": 640,
            "y": 430
        }
    }
]
